"""open_export / Export: consistent snapshot streamed with COPY and a row cap."""
import datetime

import pytest

from schema import conn
from schema.dump_model import ExportError
from schema.export import open_export

pytestmark = pytest.mark.usefixtures("master")


def build(*statements):
    with conn.rw_connection(autocommit=True) as c:
        for s in statements:
            c.execute(s)


def text(exp):
    return b"".join(exp.chunks()).decode()


def seed():
    build(
        "CREATE TABLE master.parent (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text)",
        "CREATE TABLE master.child (id integer PRIMARY KEY, pid integer REFERENCES master.parent(id), "
        "is_active boolean NOT NULL DEFAULT true)",
        "INSERT INTO master.parent (name) VALUES ('a'), ('b')",
        "INSERT INTO master.child VALUES (1, 1, true), (2, 2, false)",
    )


def test_structure_only_has_no_copy_and_no_setval():
    seed()
    exp = open_export("master", data=False, cap=0)
    out = text(exp)
    assert "CREATE TABLE" in out and "COPY " not in out and "setval" not in out
    assert exp.counts == {}


def test_data_included_copy_blocks_terminated():
    seed()
    exp = open_export("master", data=True, cap=100)
    out = text(exp)
    assert 'COPY "master"."parent" ("id", "name") FROM stdin;\n1\ta\n2\tb\n\\.\n' in out
    assert "-- parent: 2 rows" in out and "-- child: 2 rows" in out
    assert "setval" in out


def test_copy_escaping_round_trip_values():
    build("CREATE TABLE master.t (id integer PRIMARY KEY, v text)")
    vals = ["a\tb", "x\ny", "back\\slash", "\\N", "สวัสดี", "😀", None, ""]
    with conn.rw_connection(autocommit=True) as c:
        for i, v in enumerate(vals):
            c.execute("INSERT INTO master.t VALUES (%s, %s)", (i, v))
    out = text(open_export("master", data=True, cap=100))
    body = out.split("FROM stdin;\n")[1].split("\\.\n")[0].split("\n")
    assert "0\ta\\tb" in body and "1\tx\\ny" in body
    assert "2\tback\\\\slash" in body and "3\t\\\\N" in body
    assert "4\tสวัสดี" in body and "5\t😀" in body
    assert "6\t\\N" in body and "7\t" in body and "6\t\\N" != "7\t"


def test_order_parents_before_children_and_fks_after_data():
    seed()
    out = text(open_export("master", data=True, cap=100))
    assert out.index('COPY "master"."parent"') < out.index('COPY "master"."child"')
    assert out.index("FOREIGN KEY") > out.rindex("\\.\n")


def test_cap_raises_413_naming_table_before_streaming():
    seed()
    with pytest.raises(ExportError) as e:
        open_export("master", data=True, cap=3)
    assert e.value.status == 413 and "child" in str(e.value)
    open_export("master", data=False, cap=1).close()


@pytest.mark.parametrize("bad", ["nope", 'master"; DROP TABLE x;--'])
def test_unknown_schema_is_400(bad):
    with pytest.raises(ExportError) as e:
        open_export(bad, data=True, cap=10)
    assert e.value.status == 400


def test_snapshot_is_consistent():
    seed()
    exp = open_export("master", data=True, cap=100)
    build("INSERT INTO master.parent (name) VALUES ('late')")
    assert "late" not in text(exp)


def test_connection_closed_after_exhaust_and_after_early_close():
    seed()
    exp = open_export("master", data=True, cap=100)
    list(exp.chunks())
    assert exp.conn.closed
    exp = open_export("master", data=True, cap=100)
    ch = exp.chunks()
    next(ch)
    ch.close()
    assert exp.conn.closed
    exp = open_export("master", data=True, cap=100)
    exp.chunks().close()
    assert exp.conn.closed


def test_inactive_rows_are_exported():
    seed()
    out = text(open_export("master", data=True, cap=100))
    assert "2\t2\tf\n" in out


def test_filename_and_cycles():
    build(
        "CREATE TABLE master.a (id integer PRIMARY KEY, bid integer)",
        "CREATE TABLE master.b (id integer PRIMARY KEY, aid integer REFERENCES master.a(id))",
        "ALTER TABLE master.a ADD FOREIGN KEY (bid) REFERENCES master.b(id) DEFERRABLE",
        "CREATE TABLE master.s (id integer PRIMARY KEY, p integer REFERENCES master.s(id))",
        "INSERT INTO master.s VALUES (1, NULL), (2, 1)",
    )
    exp = open_export("master", data=True, cap=100)
    assert exp.filename(datetime.date(2026, 11, 9)) == "singularity-master-20261109.sql"
    out = text(exp)
    assert "2\t1\n" in out
